COMMON='''Use case: illustration-story. Asset type: ONE premium game upgrade CARD ILLUSTRATION, portrait 3:5, intended final 720x1200 RGB. Style: richly textured restrained northern myth oil painting / painterly impasto, realistic faces and materials, same collection as attached original portraits, NOT pixel art, NOT anime, no glossy 3D. This is a living myth inside an ancient archive; do not add computers, museums or science-fiction. CRITICAL composition: heads and every key spell, weapon, animal or gesture entirely within upper55% of image; faces around y15-25%, upper bodies around y25-50%; bottom40% deep blue-black simple cloak/shadow fading into quiet negative space for game text. Left/right40px safe margins at final size: no face/important weapon/animal touches side edges. Show a single composed cinematic scene, not a multi-panel sheet. No borders, card frame, letters, readable runes, logos, watermark, interface or typography. Natural anatomy, clearly separated hands, structurally sound weapons, restrained bloom; faces legible at260px wide. Preserve identity, age, hair, facial features, costume materials and painterly style from references; pose and scenario change for THIS specific upgrade.'''
def sha(f):return hashlib.sha256(f.read_bytes()).hexdigest()
def initialize():
 for directory in [BASE,FUSION]:
  for sub in ['originals','references','records','candidates','approved','previews','mipmaps']:(directory/sub).mkdir(parents=True,exist_ok=True)
 upgrades=(ROOT/'scripts/data/upgrade_db.gd').read_text();gods=(ROOT/'scripts/data/gods.gd').read_text();jobs=[]
 for id,theme,awakening in PATHS:
  god=id.split('_')[0]
  for awaken in [False,True]:
   name=id+('_awaken' if awaken else '')
   m=re.search(r'^\s*"'+re.escape(name)+r'": (\{.*\}),?$',upgrades,re.M);assert m,name
   refs=[f'assets/sprites/cards/{god}'+('_awaken' if awaken else '')+'.png']
   if awaken:refs+=[f'assets/sprites/cards/{id}.png',f'assets/sprites/cards/{god}.png']
   prompt=COMMON+'\nSubject identity: '+IDENTITIES[god]+'.\nSpecific upgrade scene: '+(awakening if awaken else theme)+'\n'+('This is the AWAKENED culmination of the companion path image, distinctly greater power and evolved scene, not a recolor, while preserving the SAME character and road motif.' if awaken else 'This is a DISTINCT PATH illustration. Show this road motif clearly, not the generic base portrait again.')
   jobs.append({'id':name,'task':'L1','god':god,'variant':'awaken' if awaken else 'path','root':str(BASE.relative_to(ROOT)),'target':f'assets/sprites/cards/{name}.png','references':refs,'prompt':prompt,'current_gameplay_source_line':m.group(0).strip(),'input_code_sha256':sha(ROOT/'scripts/data/upgrade_db.gd'),'status':'planned'})
 for key,a,b,theme in FUSIONS:
  id='fusion_'+key;m=re.search(r'^\s*"'+re.escape(key)+r'": (\{.*\}),?$',gods,re.M);assert m,key
  prompt=COMMON+'\nSubject A identity: '+IDENTITIES[a]+'.\nSubject B identity: '+IDENTITIES[b]+'.\nSpecific shared spell scene: '+theme+'\nTwo adult figures, equal scale, heads fully inside upper45%, no third main human, lighting links the pair into one coherent painting. Preserve the two separate identities, never merge facial features.'
  jobs.append({'id':id,'task':'L2','gods':[a,b],'variant':'fusion','root':str(FUSION.relative_to(ROOT)),'target':f'assets/sprites/cards/{id}.png','references':[f'assets/sprites/cards/{a}.png',f'assets/sprites/cards/{b}.png'],'prompt':prompt,'current_gameplay_source_line':m.group(0).strip(),'input_code_sha256':sha(ROOT/'scripts/data/gods.gd'),'status':'planned'})
 assert len(jobs)==60 and len(set(j['target'] for j in jobs))==60
 for j in jobs:
  assert not (ROOT/j['target']).exists(),j['target']
  (ROOT/j['root']/'records'/f'plan_{j["id"]}.json').write_text(json.dumps(j,ensure_ascii=False,indent=2)+'\n')
 (BASE/'records/plan_all_L.json').write_text(json.dumps(jobs,ensure_ascii=False,indent=2)+'\n')
 for rel in ['docs/Codex美术任务书.md','docs/美术后续任务要求.md','docs/世界观设定.md','docs/美术素材规范.md','scripts/data/upgrade_db.gd','scripts/data/gods.gd','scripts/ui/level_up_panel.gd']:
  (BASE/'records'/Path(rel).name).write_bytes((ROOT/rel).read_bytes())
 baseline={str(f.relative_to(ROOT)):sha(f) for group in ['scripts','scenes'] for f in (ROOT/group).rglob('*') if f.is_file()}
 baseline['project.godot']=sha(ROOT/'project.godot')
 (BASE/'records/code_baseline.json').write_text(json.dumps(baseline,indent=2))
 print('Prepared',len(jobs),'distinct illustrations; no existing targets overwritten.')

if __name__=='__main__':initialize()
